def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for s in lst:
        if not all(c in ['(', ')'] for c in s):
            return 'No'

    open_count = 0
    close_count = 0
    for s in lst:
        for c in s:
            if c == '(':
                open_count += 1
            else:
                close_count += 1

    if open_count == close_count:
        return 'Yes'
    else:
        return 'No'

